# hsi_transformer_autoencoder_gpu_amp.py import os, math, argparse, datetime import numpy as np from sklearn.cluster import KMeans import torch import torch.nn as nn import torch.optim as optim  from sklearn.metrics import (     silhouette_score,     calinski_harabasz_score,     davies_bouldin_score )  # Enable cudnn autotuner for performance torch.backends.cudnn.benchmark = True  try:     import matplotlib.pyplot as plt     HAS_PLT = True except Exception:     HAS_PLT = False  try:     from scipy.io import loadmat, savemat     HAS_SCIPY = True except Exception:     HAS_SCIPY = False  # ----------------------------- # Device setup: default to GPU # ----------------------------- if torch.cuda.is_available():     DEVICE = "cuda" else:     print("⚠️ CUDA not available, falling back to CPU.")     DEVICE = "cpu" print(f"Using device: {DEVICE}")   # ----------------------------- # Data utilities # ----------------------------- def metrics(X, labels):     return (         silhouette_score(X, labels),         calinski_harabasz_score(X, labels),         davies_bouldin_score(X, labels)     )  def load_cube(path):     ext = os.path.splitext(path)[1].lower()     if ext == ".npy":         cube = np.load(path)     elif ext == ".mat":         if not HAS_SCIPY:             raise RuntimeError("Install scipy to load .mat files.")         md = loadmat(path)         print("MAT keys:", [k for k in md.keys() if not k.startswith('__')])         for k in ["Images", "Image", "cube", "CUBE"]:             if k in md:                 cube = md[k]                 break         else:             raise KeyError("Cannot find 'Images' (or cube) in .mat file.")     else:         raise ValueError("Use a .npy or .mat file.")     cube = np.asarray(cube, dtype=np.float32)     if cube.ndim != 3:         raise ValueError("Cube must be HxWxB.")     return cube   def spectra_from_cube(cube):     H, W, B = cube.shape     return cube.reshape(-1, B)   def minmax_per_row(X, eps=1e-8):     xmin = X.min(axis=1, keepdims=True)     xmax = X.max(axis=1, keepdims=True)     Xn = (X - xmin) / np.maximum(xmax - xmin, eps)     return Xn, xmin, xmax   # ----------------------------- # Positional Encoding # ----------------------------- class SinusoidalPositionalEncoding(nn.Module):     def __init__(self, d_model, max_len=5000):         super().__init__()         pe = torch.zeros(max_len, d_model)         position = torch.arange(0, max_len, dtype=torch.float32).unsqueeze(1)         div_term = torch.exp(             torch.arange(0, d_model, 2, dtype=torch.float32) * (-math.log(10000.0) / d_model)         )         pe[:, 0::2] = torch.sin(position * div_term)         pe[:, 1::2] = torch.cos(position * div_term)         self.register_buffer("pe", pe)      def forward(self, x):         L = x.size(0)         return x + self.pe[:L].unsqueeze(1)   # ----------------------------- # Model # ----------------------------- class HSITokenEmbed(nn.Module):     def __init__(self, d_model):         super().__init__()         self.conv = nn.Conv1d(1, d_model, kernel_size=1)      def forward(self, x):         return self.conv(x)   class HSITransformerAutoencoder(nn.Module):     def __init__(self, d_model=64, nhead=4, d_ff=128, num_layers=2, seq_len=150, use_posenc=True):         super().__init__()         self.token = HSITokenEmbed(d_model)         encoder_layer = nn.TransformerEncoderLayer(             d_model=d_model, nhead=nhead, dim_feedforward=d_ff, batch_first=False, norm_first=True         )         self.encoder = nn.TransformerEncoder(encoder_layer, num_layers=num_layers)         self.use_posenc = use_posenc         self.posenc = SinusoidalPositionalEncoding(d_model, max_len=seq_len) if use_posenc else None         self.recon = nn.Conv1d(d_model, 1, kernel_size=1)         self.ln_final = nn.LayerNorm(d_model)      def forward(self, x):         N, B = x.shape         x1 = x.unsqueeze(1)                  # [N, 1, B]         h = self.token(x1)                   # [N, D, B]         h_tr = h.permute(2, 0, 1).contiguous()         if self.use_posenc:             h_tr = self.posenc(h_tr)         h_enc = self.encoder(h_tr)         h_enc = self.ln_final(h_enc)         z = h_enc.mean(dim=0)                # [N, D]         h_back = h_enc.permute(1, 2, 0).contiguous()         y_hat = self.recon(h_back).squeeze(1)         return y_hat, z   # ----------------------------- # Training with AMP # ----------------------------- def train_autoencoder(model, Xn_tensor, epochs=30, batch_size=256, lr=1e-3, noise_sigma=0.01, n_clusters=5):     model.to(DEVICE)     opt = optim.Adam(model.parameters(), lr=lr)     loss_fn = nn.MSELoss()     scaler = torch.cuda.amp.GradScaler(enabled=(DEVICE == "cuda"))      N, B = Xn_tensor.shape     num_batches = math.ceil(N / batch_size)          # Track metrics over time     metric_history = {'silhouette': [], 'calinski_harabasz': [], 'davies_bouldin': [], 'epochs': []}          model.train()      for ep in range(1, epochs + 1):         perm = torch.randperm(N, device=DEVICE)         epoch_loss = 0.0         for bi in range(num_batches):             idx = perm[bi * batch_size : (bi + 1) * batch_size]             xb = Xn_tensor[idx, :]              if noise_sigma > 0:                 noise = noise_sigma * torch.randn_like(xb)                 xb_in = (xb + noise).clamp(0.0, 1.0)             else:                 xb_in = xb              with torch.cuda.amp.autocast(enabled=(DEVICE == "cuda")):                 y_hat, _ = model(xb_in)                 loss = loss_fn(y_hat, xb)              opt.zero_grad()             scaler.scale(loss).backward()             scaler.step(opt)             scaler.update()              epoch_loss += loss.item()                  # Calculate metrics for this epoch         model.eval()         with torch.no_grad():             _, Z_epoch = model(Xn_tensor)             Z_np = Z_epoch.cpu().numpy()                  # Cluster and compute metrics         km = KMeans(n_clusters=n_clusters, n_init=10, random_state=42)         labels = km.fit_predict(Z_np)         sil, ch, db = metrics(Z_np, labels)                  metric_history['silhouette'].append(sil)         metric_history['calinski_harabasz'].append(ch)         metric_history['davies_bouldin'].append(db)         metric_history['epochs'].append(ep)                  print(f"Epoch {ep:03d}/{epochs} | loss {epoch_loss/num_batches:.6f} | sil {sil:.4f} | CH {ch:.2f} | DB {db:.4f}")                  model.train()          return model, metric_history   # ----------------------------- # Inference # ----------------------------- @torch.no_grad() def reconstruct_and_embed(model, Xn_tensor, batch_size=512):     model.eval().to(DEVICE)     N, B = Xn_tensor.shape     yhat = np.zeros((N, B), dtype=np.float32)      _, ztest = model(Xn_tensor[:2])     D = ztest.shape[1]     Z = np.zeros((N, D), dtype=np.float32)      num_batches = math.ceil(N / batch_size)     for bi in range(num_batches):         s = bi * batch_size         e = min((bi + 1) * batch_size, N)         xb = Xn_tensor[s:e]         with torch.cuda.amp.autocast(enabled=(DEVICE == "cuda")):             yh, z = model(xb)         yhat[s:e] = yh.cpu().numpy()         Z[s:e] = z.cpu().numpy()     return yhat, Z   def unscale_rows(Xn, xmin, xmax, eps=1e-8):     return Xn * np.maximum(xmax - xmin, eps) + xmin   # ----------------------------- # Main # ----------------------------- def main():     script_dir = os.path.dirname(os.path.abspath(__file__))     cube_path = os.path.join(script_dir, "cube.mat")      if not os.path.isfile(cube_path):         raise FileNotFoundError(f"cube.mat not found in {script_dir}")      cube = load_cube(cube_path)     H, W, B = cube.shape     print(f"Loaded cube: {H}x{W}x{B}")      X = spectra_from_cube(cube)     Xn, xmin, xmax = minmax_per_row(X)      Xn_tensor = torch.from_numpy(Xn).to(DEVICE)      model = HSITransformerAutoencoder(         d_model=64, nhead=4, d_ff=128, num_layers=2, seq_len=B, use_posenc=True     )      model, metric_history = train_autoencoder(model, Xn_tensor, epochs=30, batch_size=256, lr=1e-3, noise_sigma=0.01, n_clusters=5)      Xrec_n, Z = reconstruct_and_embed(model, Xn_tensor, batch_size=512)     Xrec = unscale_rows(Xrec_n, xmin, xmax)     rec_cube = Xrec.reshape(H, W, B)      print("Clustering embeddings with k-means...")     km = KMeans(n_clusters=5, n_init=10, random_state=42)     labels = km.fit_predict(Z)     seg_map = labels.reshape(H, W)     print("sil / CH / DB =", metrics(Z, labels))      mse_per_spec = ((Xn - Xrec_n) ** 2).mean(axis=1)     print(f"Mean per-spectrum MSE (normalized): {mse_per_spec.mean():.6f}")      ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")     np.save(os.path.join(script_dir, f"recCube_{ts}.npy"), rec_cube)     np.save(os.path.join(script_dir, f"segMap_{ts}.npy"), seg_map)      try:         savemat(os.path.join(script_dir, f"out_{ts}.mat"), {             "recCube": rec_cube,             "segMap": seg_map,             "embedFeatures": Z         })         print(f"Saved outputs to {script_dir}: recCube_{ts}.npy, segMap_{ts}.npy, out_{ts}.mat")     except ImportError:         print("scipy not installed → skipped .mat save.")      if HAS_PLT:         # Plot metrics over time         fig, axes = plt.subplots(1, 3, figsize=(15, 4))         fig.suptitle('Clustering Metrics During Training')                  axes[0].plot(metric_history['epochs'], metric_history['silhouette'], 'b-o')         axes[0].set_title('Silhouette Score (higher is better)')         axes[0].set_xlabel('Epoch')         axes[0].set_ylabel('Score')         axes[0].grid(True)                  axes[1].plot(metric_history['epochs'], metric_history['calinski_harabasz'], 'g-o')         axes[1].set_title('Calinski-Harabasz Index (higher is better)')         axes[1].set_xlabel('Epoch')         axes[1].set_ylabel('Score')         axes[1].grid(True)                  axes[2].plot(metric_history['epochs'], metric_history['davies_bouldin'], 'r-o')         axes[2].set_title('Davies-Bouldin Index (lower is better)')         axes[2].set_xlabel('Epoch')         axes[2].set_ylabel('Score')         axes[2].grid(True)                  plt.tight_layout()         plt.show()     else:         print("matplotlib not available; skipping plots.")   if __name__ == "__main__":     main()